mapper.update:
update platform_customer_service set name = #{name}, config_json = #{configJson},
    status = #{status}, runtime_epoch = #{runtimeEpoch}, current_release_id = #{currentReleaseId},
    revision = revision + 1, update_time = #{updateTime}
where tenant_id = #{tenantId} and id = #{id} and revision = #{revision}

mapper.select:
select count(*) from platform_customer_session s
join platform_customer_service a on a.tenant_id = s.tenant_id and a.id = s.app_id and a.runtime_epoch = s.runtime_epoch
left join platform_customer_channel c on c.tenant_id = s.tenant_id and c.id = s.channel_id
where s.tenant_id = #{tenantId} and s.user_id = #{userId} and s.app_id = #{appId}
    and s.status = 'ACTIVE' and s.expires_at > #{now}
    and (s.channel_id is null or (c.status = 'ACTIVE' and c.expires_at > #{now}
        and c.revision = s.channel_revision and c.app_id = s.app_id and c.release_id = s.release_id))

select * from platform_customer_session
where tenant_id = #{tenantId} and (user_id = #{userId} or (user_id = 0 and visitor_token_hash is not null)) and app_id = #{appId}

    and (create_time < #{before.createTime}
        or (create_time = #{before.createTime} and id < #{before.id}))

order by create_time desc, id desc limit 21

mapper.update:
update platform_customer_session set turn_count = turn_count + 1
where tenant_id = #{tenantId} and user_id = #{userId} and id = #{id}
    and status = 'ACTIVE' and turn_count = #{turnCount}

update platform_customer_turn set answer_parts_json = #{answerPartsJson}
where tenant_id = #{tenantId} and session_id = #{sessionId} and id = #{id}
    and status = 'RUNNING' and deadline > #{finishedTime}

update platform_customer_turn set status = #{status}, answer = #{answer},
    citations_json = #{citationsJson}, intent_json = #{intentJson}, error_code = #{errorCode},
    input_tokens = #{inputTokens}, output_tokens = #{outputTokens},
    total_tokens = #{totalTokens}, usage_source = #{usageSource}, finished_time = #{finishedTime}
where tenant_id = #{tenantId} and session_id = #{sessionId} and id = #{id}
    and status = 'RUNNING' and deadline > #{finishedTime}

update platform_customer_turn set status = 'INTERRUPTED', error_code = 'TURN_EXPIRED', finished_time = #{now}
where tenant_id = #{tenantId} and session_id = #{sessionId}
    and status = 'RUNNING' and deadline <= #{now}

update platform_customer_turn set status = 'INTERRUPTED', error_code = 'TURN_INTERRUPTED', finished_time = #{now}
where tenant_id = #{tenantId} and session_id = #{sessionId} and status = 'RUNNING'
and id = #{id}

mapper.select:
select count(*) from platform_customer_turn t
join platform_customer_session s on s.tenant_id = t.tenant_id and s.id = t.session_id
join platform_customer_service a on a.tenant_id = s.tenant_id and a.id = s.app_id
left join platform_customer_channel c on c.tenant_id = s.tenant_id and c.id = s.channel_id
where t.tenant_id = #{tenantId} and t.session_id = #{sessionId} and t.id = #{turnId}
    and t.status = 'RUNNING' and t.deadline > #{now}
    and s.user_id = #{userId} and s.status = 'ACTIVE' and s.expires_at > #{now}
    and a.status = 'ACTIVE' and a.runtime_epoch = s.runtime_epoch
    and (s.channel_id is null or (c.status = 'ACTIVE' and c.expires_at > #{now}
        and c.revision = s.channel_revision and c.app_id = s.app_id and c.release_id = s.release_id))
